engineering_specifics.example_code:
int primary_fd = posix_openpt(O_RDWR | O_NOCTTY);
if (primary_fd == -1) { perror("posix_openpt"); exit(1); }
if (grantpt(primary_fd) == -1) { perror("grantpt"); exit(1); }
if (unlockpt(primary_fd) == -1) { perror("unlockpt"); exit(1); }
char replica_name[128];
if (ptsname_r(primary_fd, replica_name, sizeof(replica_name)) == -1) { perror("ptsname_r"); exit(1); }
int replica_fd = open(replica_name, O_RDWR);

pid_t pid = fork();
if (pid == 0) { // child
  if (setsid() == -1) { perror("setsid"); exit(1); }
  int replica_fd = open(replica_name, O_RDWR);
  if (replica_fd == -1) { perror("open replica"); exit(1); }
  // replica becomes controlling terminal automatically on first open after setsid
  if (setpgid(0, 0) == -1) { perror("setpgid"); exit(1); }
  tcsetpgrp(replica_fd, getpid()); // set as foreground
  dup2(replica_fd, 0); dup2(replica_fd, 1); dup2(replica_fd, 2);
  close(replica_fd);
  execl("/bin/sh", "sh", NULL);
} else { // parent
  setpgid(pid, pid); // avoid race: ensure child is in own group
}

