engineering_specifics.example_code:
volatile sig_atomic_t winch_received = 0;

void handle_winch(int sig) {
  winch_received = 1; // async-signal-safe
}

int main() {
  struct sigaction sa;
  sa.sa_handler = handle_winch;
  sigemptyset(&sa.sa_mask);
  sa.sa_flags = SA_RESTART; // restart interrupted syscalls
  sigaction(SIGWINCH, &sa, NULL);

  while (running) {
    if (winch_received) {
      winch_received = 0;
      struct winsize ws;
      if (ioctl(STDIN_FILENO, TIOCGWINSZ, &ws) == 0) {
        // propagate to PTY primary:
        ioctl(primary_fd, TIOCSWINSZ, &ws);
      }
    }
    // main loop
  }
}

engineering_specifics.zombie_prevention:
// Method 1: SA_NOCLDWAIT
struct sigaction sa;
sa.sa_handler = SIG_DFL;
sa.sa_flags = SA_NOCLDWAIT;
sigaction(SIGCHLD, &sa, NULL);

// Method 2: waitpid in handler
void sigchld_handler(int sig) {
  int saved_errno = errno;
  while (waitpid(-1, NULL, WNOHANG) > 0);
  errno = saved_errno;
}

engineering_specifics.fd_leak_prevention:
// In child after fork:
close(primary_fd); // parent keeps this
dup2(replica_fd, 0);
dup2(replica_fd, 1);
dup2(replica_fd, 2);
if (replica_fd > 2) close(replica_fd);

// Set CLOEXEC on primary:
fcntl(primary_fd, F_SETFD, FD_CLOEXEC);

engineering_specifics.error_handling_pattern:
int primary_fd = posix_openpt(O_RDWR | O_NOCTTY);
if (primary_fd == -1) goto error;
if (grantpt(primary_fd) == -1) goto error_close_primary;
if (unlockpt(primary_fd) == -1) goto error_close_primary;
// ... success path
return 0;

error_close_primary:
  close(primary_fd);
error:
  return -1;

engineering_specifics.graceful_shutdown:
// Send SIGHUP to session
kill(-session_pgid, SIGHUP);
// Wait up to 2 seconds
for (int i = 0; i < 20; i++) {
  if (waitpid(session_pid, NULL, WNOHANG) > 0) break;
  usleep(100000); // 100ms
}
// Force kill if still alive
kill(-session_pgid, SIGKILL);
waitpid(session_pid, NULL, 0);
close(primary_fd);

engineering_specifics.security_checks:
// Validate replica path
char *replica = ptsname(primary_fd);
if (strncmp(replica, "/dev/pts/", 9) != 0 &&
    strncmp(replica, "/dev/tty", 8) != 0) {
  // Unexpected path, possible attack
  return -1;
}
// Check ownership after grantpt
struct stat st;
if (fstat(replica_fd, &st) == -1) return -1;
if (st.st_uid != getuid()) {
  // Ownership mismatch
  return -1;
}
